/// <summary>
/// AVAExtension for object AVAMailAgain in form SalesQuotationListPage
/// </summary>
[ExtensionOf(formControlStr(SalesQuotationListPage, AVAMailAgain))]
final class AVASalesQuotationListPageFrm_AVAMailAgain_Extension
{
}

Method.Source:
/// <summary>
/// clicked method
/// </summary>
public void clicked()
{
    next clicked();

    //element.avaCreateEmail(this);
    FormDataSource          quotationDS = this.formRun().dataSource(tableStr(SalesQuotationTable));
    SalesQuotationTable     salesQuotationTable;
    #define.sendGAEB('sendGAEB')
    if (quotationDS)
    {
        salesQuotationTable = quotationDS.cursor();
    }
    CustQuotationJour           lastCustQuotationJour = CustQuotationJour::avaFindLatestQuotation(salesQuotationTable.QuotationId);
    Args args = new Args();
    args.record(lastCustQuotationJour);
    args.caller(this);
    args.parm(#sendGAEB);

    new MenuFunction(menuItemActionStr(AVAERQuotationEmailCreation), MenuItemType::Action).run(args);
}
